head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil25107";
scwin.selFrm = undefined;
scwin.sub_chargeChangeDate_Y = null;
scwin.sub_chargeChangeDate_M = null;
scwin.sub_chargeChangeDate_D = null;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — spotIsuTrdMktTpCd, isurCd

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_attrReals();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil25107.onpageload' });
    }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "td_126", attr: "__html", fn: function () { return ([String(((1 === "1") ? "책임자" : "담당자"))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? (String(((1 === "1") ? "책임자" : "담당자")) + "소재지<br/>회사 주소") : ''); } },
        { childId: "td_126_r1", attr: "__html", fn: function () { return ([String(((2 === "1") ? "책임자" : "담당자"))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? (String(((2 === "1") ? "책임자" : "담당자")) + "소재지<br/>회사 주소") : ''); } },
        { childId: "td_126_r2", attr: "__html", fn: function () { return ([String(((3 === "1") ? "책임자" : "담당자"))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? (String(((3 === "1") ? "책임자" : "담당자")) + "소재지<br/>회사 주소") : ''); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_otherwise_46", fn: function(){ return (!((1===1) || (1===2))); } }, { id: "c_when_48_txt", fn: function(){ return ((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "") ==='2'); } }, { id: "c_otherwise_49", fn: function(){ return (!(((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "") ==='2'))); } }, { id: "c_when_44_r1_txt", fn: function(){ return ((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "") ==='2'); } }, { id: "c_otherwise_45_r1", fn: function(){ return (!(((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "") ==='2'))); } }, { id: "c_otherwise_46_r1", fn: function(){ return (!((2===1) || (2===2))); } }, { id: "c_when_48_r1_txt", fn: function(){ return ((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "") ==='2'); } }, { id: "c_otherwise_49_r1", fn: function(){ return (!(((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "") ==='2'))); } }, { id: "c_otherwise_46_r2", fn: function(){ return (!((3===1) || (3===2))); } }, { id: "c_when_48_r2_txt", fn: function(){ return ((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "") ==='2'); } }, { id: "c_otherwise_49_r2", fn: function(){ return (!(((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "") ==='2'))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.initValue();
        scwin.chkChrgDesignReadonly();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil25107.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
