        if ($c.util.getComponent('dma_ModifyReq').get('disclsProfsYn') === '') {
            $c.util.getComponent('dma_ModifyReq').set('disclsProfsYn', '-');
        }
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_locZipcd'))) {
        return;
    }
    if (!($c.fil.isZipCodeInput($c.util.getComponent('ipt_locZipcd')))) {
        await $c.win.alert('우편번호는 숫자만 입력하세요');
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_locAddr'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = ""; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_locAddr'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = ""; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_locDtlAddr'))) {
        return;
    }
    $c.util.getComponent('dma_ModifyReq').set('telNo', $c.util.getComponent('ipt_telNo1').getValue()+ '-' + $c.util.getComponent('ipt_telNo2').getValue()+ '-' + $c.util.getComponent('ipt_telNo3').getValue());
    $c.util.getComponent('dma_ModifyReq').set('cellphoneNo', $c.util.getComponent('slc_cellphoneNo1').getValue()+ '-' + $c.util.getComponent('ipt_cellphoneNo2').getValue()+ '-' + $c.util.getComponent('ipt_cellphoneNo3').getValue());
    $c.util.getComponent('dma_ModifyReq').set('faxNo', $c.util.getComponent('ipt_faxNo1').getValue()+ '-' + $c.util.getComponent('ipt_faxNo2').getValue()+ '-' + $c.util.getComponent('ipt_faxNo3').getValue());
    $c.util.getComponent('dma_ModifyReq').set('email', $c.str.trim($c.util.getComponent('ipt_email1').getValue()) + '@' + $c.str.trim($c.util.getComponent('ipt_email2').getValue()));
    $c.util.getComponent('dma_ModifyReq').set('chrgDesignDd', $c.util.getComponent('ipt_chrgDesignYear').getValue()+ $c.util.getComponent('ipt_chrgDesignMonth').getValue()+ $c.util.getComponent('ipt_chrgDesignDay').getValue());
    if (!$c.str.isEmail($c.util.getComponent('dma_ModifyReq').get('email'))) {
        return;
    }
    $c.util.getComponent('dma_ModifyReq').set('doFlag', _doFlag);
    $c.util.getComponent('dma_ModifyReq').set('method', 'modifyBondDisclsChrg');
    frm.action = 'corpDiscls.do';
    await scwin.tx_fn_Modify();
};

/**
