        ((v) => { let cur = String(v ?? ""); for (let i = 2; i >= 1; i--) { const idx = cur.lastIndexOf("@"); const part = cur.substring(idx + 1); const c = $c.util.getComponent("email" + i); if (c && c.setValue) { c.setValue(part); } cur = cur.substring(0, idx); } })($c.util.getComponent('dma_ModifyReq').get('email'));
        const chrgDesignDdVal = $c.util.getComponent('dma_ModifyReq').get('chrgDesignDd');
