/**
 * @method
 * @name print
 * @description print 처리
 * @param {String} _isurCd _isurCd
 * @param {String} _chrgTpCd _chrgTpCd
 * @returns {void}
 * @hidden N
 */
scwin.print = function (_isurCd, _chrgTpCd) {
    const chrgTpCd = "7" + _chrgTpCd;
    const rexName = "RLDFIL00027";
    const dataLocation = "/account/reportPrint.do?method=personalNewReport&isurCd=" + _isurCd + "&chrgTpCd=" + chrgTpCd;
    $.ajax({ type: "POST", async: false, url: dataLocation, data: {  }, success: async function(data) {
                const result = (typeof data === "string" ? (typeof data === "string" ? JSON.parse(data) : data) : data);
                $c.util.getComponent('dma_ModifyReq').set('ncomNm', result.companyName);
                $c.util.getComponent('dma_ModifyReq').set('ncharge', result.charge);
                $c.util.getComponent("dma_ModifyReq").set("nbeforeChargeName", result.beforeChargeName);
                $c.util.getComponent("dma_ModifyReq").set("nafterChargeName", result.afterChargeName);
                $c.util.getComponent('dma_ModifyReq').set('nTempleteCd', rexName);
                if (result.chargeChangeDate) {
                    const sub_chargeChangeDate = result.chargeChangeDate;
                    scwin.sub_chargeChangeDate_Y = sub_chargeChangeDate.substring(0, 4);
                    scwin.sub_chargeChangeDate_M = sub_chargeChangeDate.substring(4, 6);
                    scwin.sub_chargeChangeDate_D = sub_chargeChangeDate.substring(6, 8);
                    $c.util.getComponent("dma_ModifyReq").set("nchargeChangeDate", scwin.sub_chargeChangeDate_Y + "년 " + scwin.sub_chargeChangeDate_M + "월 " + scwin.sub_chargeChangeDate_D + "일");
                } else {
                    $c.util.getComponent("dma_ModifyReq").set("nchargeChangeDate", result.chargeChangeDate);
                }
                await scwin.tx_fn_Print();
            }, error: async function(request, status, error) {
                await $c.win.alert("장애발생.");
                return;
            }, complete: function() {

            } });
};

/**
