 * @name chkChrgDesignReadonly
 * @description chk Chrg Design Readonly 처리
 * @returns {void}
 * @hidden N
 */
scwin.chkChrgDesignReadonly = function () {
    let frm;
    for (let i = 1; i <= 3; i++) {
        frm = $c.util.getComponent('corpDisclsChrgForm' + i);
        if (($c.util.getComponent('ipt_chrgNm').getValue() == null ? '' : String($c.util.getComponent('ipt_chrgNm').getValue())) !== '') {
            $c.util.getComponent('ipt_chrgNm').readOnly = true;
            $c.util.getComponent('ipt_chrgDesignYear').readOnly = true;
            $c.util.getComponent('ipt_chrgDesignMonth').readOnly = true;
            $c.util.getComponent('ipt_chrgDesignDay').readOnly = true;
            $c.util.getComponent('ipt_chrgDesignYear').setStyle("border", 'none');
            $c.util.getComponent('ipt_chrgDesignMonth').setStyle("border", 'none');
            $c.util.getComponent('ipt_chrgDesignDay').setStyle("border", 'none');
        } else {
            $c.util.getComponent('ipt_chrgNm').readOnly = false;
            $c.util.getComponent('ipt_chrgDesignYear').readOnly = false;
            $c.util.getComponent('ipt_chrgDesignMonth').readOnly = false;
            $c.util.getComponent('ipt_chrgDesignDay').readOnly = false;
            $c.util.getComponent('ipt_chrgDesignYear').setStyle("border", 'solid 1px #A0A0A0');
            $c.util.getComponent('ipt_chrgDesignMonth').setStyle("border", 'solid 1px #A0A0A0');
            $c.util.getComponent('ipt_chrgDesignDay').setStyle("border", 'solid 1px #A0A0A0');
        }
    }
};

/**
